using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Text;
using Leptonica;

namespace Leptonica.Managed.Tests.Core;

/// <summary>
/// CFormat against tables generated by tools/cformat_gen (glibc printf/sscanf, which agree
/// with the MSVC UCRT on everything in the tables) plus hand-written cases for the places
/// where the UCRT differs from glibc (NaN spelling, 32-bit long).
/// </summary>
public class CFormatTests
{
    /*------------------------------- tables ----------------------------------*/

    private static string Unescape(string s)
    {
        if (s.IndexOf('\\') < 0)
            return s;
        var sb = new StringBuilder(s.Length);
        for (int i = 0; i < s.Length; i++)
        {
            if (s[i] != '\\')
            {
                sb.Append(s[i]);
                continue;
            }
            i++;
            if (s[i] == '\\')
                sb.Append('\\');
            else if (s[i] == 'x')
            {
                sb.Append((char)Convert.ToInt32(s.Substring(i + 1, 2), 16));
                i += 2;
            }
            else
                throw new InvalidDataException("bad escape in table");
        }
        return sb.ToString();
    }

    private static string[][] ReadTable(string name)
    {
        string path = Path.Combine(AppContext.BaseDirectory, "Core", "Data", name);
        var rows = new List<string[]>();
        foreach (string line in File.ReadLines(path))
        {
            if (line.Length == 0)
                continue;
            string[] cols = line.Split('\t');
            for (int i = 0; i < cols.Length; i++)
                cols[i] = Unescape(cols[i]);
            rows.Add(cols);
        }
        return rows.ToArray();
    }

    private static object ParseArg(string a)
    {
        string v = a.Substring(2);
        switch (a[0])
        {
            case 'i': return int.Parse(v, CultureInfo.InvariantCulture);
            case 'u': return uint.Parse(v, CultureInfo.InvariantCulture);
            case 'l': return long.Parse(v, CultureInfo.InvariantCulture);
            case 'U': return ulong.Parse(v, CultureInfo.InvariantCulture);
            case 'd': return BitConverter.Int64BitsToDouble((long)Convert.ToUInt64(v, 16));
            case 's': return v;
            default: throw new InvalidDataException("bad arg " + a);
        }
    }

    [Fact]
    public void SprintfMatchesTable()
    {
        string[][] rows = ReadTable("cformat_printf.tsv");
        Assert.True(rows.Length > 1000);
        var failures = new List<string>();
        foreach (string[] row in rows)
        {
            var args = new object[row.Length - 2];
            for (int i = 0; i < args.Length; i++)
                args[i] = ParseArg(row[i + 2]);
            string actual = CFormat.Sprintf(row[0], args);
            if (actual != row[1])
                failures.Add($"[{row[0]}] {string.Join(" ", row, 2, row.Length - 2)}: expected <{row[1]}> got <{actual}>");
        }
        Assert.True(failures.Count == 0, failures.Count + " mismatches, first:\n" + string.Join("\n", failures.GetRange(0, Math.Min(15, failures.Count))));
    }

    private static string Describe(object? v) => v switch
    {
        null => "-",
        sbyte or short or int or long => "i:" + Convert.ToInt64(v, CultureInfo.InvariantCulture),
        byte or ushort or uint or ulong => "u:" + Convert.ToUInt64(v, CultureInfo.InvariantCulture),
        double d => "d:0x" + BitConverter.DoubleToInt64Bits(d).ToString("x16"),
        float f => "f:0x" + BitConverter.DoubleToInt64Bits(f).ToString("x16"),
        string s => "s:" + s,
        _ => throw new InvalidOperationException(v.GetType().Name),
    };

    [Fact]
    public void SscanfMatchesTable()
    {
        string[][] rows = ReadTable("cformat_scanf.tsv");
        Assert.True(rows.Length > 500);
        var failures = new List<string>();
        foreach (string[] row in rows)
        {
            int expectedRet = int.Parse(row[2], CultureInfo.InvariantCulture);
            int ret = CFormat.Sscanf(row[1], row[0], out object?[] values);
            var parts = new List<string>();
            foreach (object? v in values)
                parts.Add(Describe(v));
            string actual = ret + " " + string.Join(" ", parts);
            string expected = expectedRet + " " + string.Join(" ", row, 3, row.Length - 3);
            if (actual != expected)
                failures.Add($"[{row[0]}] input <{row[1]}>: expected <{expected}> got <{actual}>");
        }
        Assert.True(failures.Count == 0, failures.Count + " mismatches, first:\n" + string.Join("\n", failures.GetRange(0, Math.Min(25, failures.Count))));
    }

    /*------------------------------- printf ----------------------------------*/

    [Fact]
    public void SpecialFloatValues()
    {
        double qnanInd = BitConverter.Int64BitsToDouble(unchecked((long)0xFFF8000000000000UL));
        double qnan = BitConverter.Int64BitsToDouble(0x7FF8000000000000L);
        double qnanPayload = BitConverter.Int64BitsToDouble(0x7FF8000000000123L);
        double snan = BitConverter.Int64BitsToDouble(0x7FF0000000000001L);
        Assert.Equal("-nan(ind)", CFormat.Sprintf("%f", double.NaN));
        Assert.Equal("-nan(ind)", CFormat.Sprintf("%g", qnanInd));
        Assert.Equal("nan", CFormat.Sprintf("%e", qnan));
        Assert.Equal("nan", CFormat.Sprintf("%f", qnanPayload));
        Assert.Equal("nan(snan)", CFormat.Sprintf("%f", snan));
        Assert.Equal("-NAN(IND)", CFormat.Sprintf("%F", double.NaN));
        Assert.Equal("NAN", CFormat.Sprintf("%E", qnan));
        Assert.Equal("inf", CFormat.Sprintf("%f", double.PositiveInfinity));
        Assert.Equal("-inf", CFormat.Sprintf("%.2e", double.NegativeInfinity));
        Assert.Equal("INF", CFormat.Sprintf("%G", double.PositiveInfinity));
        Assert.Equal("+inf", CFormat.Sprintf("%+f", double.PositiveInfinity));
        Assert.Equal(" inf", CFormat.Sprintf("% f", double.PositiveInfinity));
        Assert.Equal("       inf", CFormat.Sprintf("%10.3f", double.PositiveInfinity));
        Assert.Equal("inf       |", CFormat.Sprintf("%-10f|", double.PositiveInfinity));
        Assert.Equal("       inf", CFormat.Sprintf("%010f", double.PositiveInfinity));
        Assert.Equal("  -nan(ind)", CFormat.Sprintf("%11f", double.NaN));
    }

    [Fact]
    public void IntegerTruncationFollowsWindowsTypes()
    {
        Assert.Equal("1", CFormat.Sprintf("%d", 0x1_0000_0001L));
        Assert.Equal("1", CFormat.Sprintf("%ld", 0x1_0000_0001L));        // long is 32 bits
        Assert.Equal("4294967297", CFormat.Sprintf("%lld", 0x1_0000_0001L));
        Assert.Equal("-1", CFormat.Sprintf("%ld", 0xFFFFFFFFL));
        Assert.Equal("4294967295", CFormat.Sprintf("%lu", -1));
        Assert.Equal("ffffffff", CFormat.Sprintf("%lx", -1L));
        Assert.Equal("ffffffffffffffff", CFormat.Sprintf("%llx", -1));
        Assert.Equal("18446744073709551615", CFormat.Sprintf("%zu", -1L));
        Assert.Equal("9223372036854775807", CFormat.Sprintf("%jd", long.MaxValue));
        Assert.Equal("-9223372036854775808", CFormat.Sprintf("%lld", long.MinValue));
        Assert.Equal("9223372036854775808", CFormat.Sprintf("%llu", long.MinValue));
        Assert.Equal("44", CFormat.Sprintf("%hhd", 300));
        Assert.Equal("-1", CFormat.Sprintf("%hhd", 255));
        Assert.Equal("255", CFormat.Sprintf("%hhu", -1));
        Assert.Equal("65535", CFormat.Sprintf("%hu", -1));
        Assert.Equal("-32768", CFormat.Sprintf("%hd", 32768));
        Assert.Equal("4294967295", CFormat.Sprintf("%u", -1));
        Assert.Equal("ffffffff", CFormat.Sprintf("%x", -1));
        Assert.Equal("FFFF", CFormat.Sprintf("%hX", -1));
        Assert.Equal("37777777777", CFormat.Sprintf("%o", -1));
        Assert.Equal("-2147483648", CFormat.Sprintf("%d", int.MinValue));
        Assert.Equal("4294967295", CFormat.Sprintf("%I32u", uint.MaxValue));
        Assert.Equal("18446744073709551615", CFormat.Sprintf("%I64u", ulong.MaxValue));
        Assert.Equal("65", CFormat.Sprintf("%d", (byte)65));
        Assert.Equal("1", CFormat.Sprintf("%d", true));
    }

    [Fact]
    public void LongDoubleModifierIsDouble()
    {
        Assert.Equal("1.500000", CFormat.Sprintf("%lf", 1.5));
        Assert.Equal("1.500000", CFormat.Sprintf("%Lf", 1.5));
        Assert.Equal("1.5e+00", CFormat.Sprintf("%.1Le", 1.5));
    }

    [Fact]
    public void FloatArgumentIsPromotedToDouble()
    {
        Assert.Equal("0.100000", CFormat.Sprintf("%f", 0.1f));
        Assert.Equal("0.10000000149011611938", CFormat.Sprintf("%.20f", 0.1f));
    }

    [Fact]
    public void ExactExpansionAndHalfEvenRounding()
    {
        Assert.Equal("0.100000000000000005551115123126", CFormat.Sprintf("%.30f", 0.1));
        Assert.Equal("0", CFormat.Sprintf("%.0f", 0.5));
        Assert.Equal("2", CFormat.Sprintf("%.0f", 1.5));
        Assert.Equal("2", CFormat.Sprintf("%.0f", 2.5));
        Assert.Equal("4", CFormat.Sprintf("%.0f", 3.5));
        Assert.Equal("0.2", CFormat.Sprintf("%.1f", 0.25));
        Assert.Equal("0.12", CFormat.Sprintf("%.2f", 0.125));
        Assert.Equal("0.14", CFormat.Sprintf("%.2f", 0.135));   // 0.135 is above the tie
        Assert.Equal("1e+01", CFormat.Sprintf("%.0e", 9.5));
        Assert.Equal("1.0e+01", CFormat.Sprintf("%.1e", 9.96));
        Assert.Equal("1000", CFormat.Sprintf("%.0f", 999.5));
        Assert.Equal("4.940656e-324", CFormat.Sprintf("%e", double.Epsilon));
        Assert.Equal("1.797693e+308", CFormat.Sprintf("%e", double.MaxValue));
        Assert.Equal("1e+16", CFormat.Sprintf("%g", 1e16));
        Assert.Equal("100000", CFormat.Sprintf("%g", 1e5));
        Assert.Equal("1e+06", CFormat.Sprintf("%g", 1e6));
        Assert.Equal("0.0001", CFormat.Sprintf("%g", 1e-4));
        Assert.Equal("1e-05", CFormat.Sprintf("%g", 1e-5));
        Assert.Equal("0", CFormat.Sprintf("%g", 0.0));
        Assert.Equal("-0", CFormat.Sprintf("%g", -0.0));
        Assert.Equal("-0.000000", CFormat.Sprintf("%f", -0.0));
        Assert.Equal("0.00000", CFormat.Sprintf("%#g", 0.0));
        Assert.Equal("1.00000e+06", CFormat.Sprintf("%#g", 999999.5));   // glibc prints "1.e+06"
        Assert.Equal("1.00e+03", CFormat.Sprintf("%#.3g", 999.5));
        Assert.Equal("1.e+06", CFormat.Sprintf("%#.0g", 999999.5));
        Assert.Equal("1e+100", CFormat.Sprintf("%g", 1e100));
        Assert.Equal("1.000000e-100", CFormat.Sprintf("%e", 1e-100));

        string big = CFormat.Sprintf("%f", double.MaxValue);
        Assert.Equal(309 + 7, big.Length);
        Assert.StartsWith("179769313486231570814527423731704356798070", big);
        Assert.EndsWith("858368.000000", big);
    }

    [Fact]
    public void RandomDoublesRoundTripWith17Digits()
    {
        var rng = new Random(12345);
        var raw = new byte[8];
        for (int i = 0; i < 20000; i++)
        {
            rng.NextBytes(raw);
            double d = BitConverter.ToDouble(raw, 0);
            if (!double.IsFinite(d))
                continue;
            string g = CFormat.Sprintf("%.17g", d);
            Assert.Equal(BitConverter.DoubleToInt64Bits(d), BitConverter.DoubleToInt64Bits(double.Parse(g, CultureInfo.InvariantCulture)));
            string e = CFormat.Sprintf("%.16e", d);
            Assert.Equal(BitConverter.DoubleToInt64Bits(d), BitConverter.DoubleToInt64Bits(double.Parse(e, CultureInfo.InvariantCulture)));
        }
    }

    [Fact]
    public void StringsAndChars()
    {
        Assert.Equal("(null)", CFormat.Sprintf("%s", (object?)null));
        Assert.Equal("ab", CFormat.Sprintf("%.2s", "abcd"));
        Assert.Equal("  ab", CFormat.Sprintf("%4.2s", "abcd"));
        Assert.Equal("A", CFormat.Sprintf("%c", 65));
        Assert.Equal("A", CFormat.Sprintf("%c", 'A'));
        Assert.Equal("A", CFormat.Sprintf("%c", 65 + 256));
        Assert.Equal("\0", CFormat.Sprintf("%c", 0));
        Assert.Equal("100%", CFormat.Sprintf("%d%%", 100));
        Assert.Equal("%", CFormat.Sprintf("%%"));
        Assert.Equal("plain", CFormat.Sprintf("plain"));
        Assert.Equal("", CFormat.Sprintf(""));
    }

    [Fact]
    public void InvalidUseThrows()
    {
        Assert.Throws<ArgumentException>(() => CFormat.Sprintf("%d"));
        Assert.Throws<ArgumentException>(() => CFormat.Sprintf("%d", "x"));
        Assert.Throws<ArgumentException>(() => CFormat.Sprintf("%f", 1));
        Assert.Throws<ArgumentException>(() => CFormat.Sprintf("%s", 1));
        Assert.Throws<ArgumentException>(() => CFormat.Sprintf("%*d", 5));
        Assert.Throws<FormatException>(() => CFormat.Sprintf("%y", 1));
        Assert.Throws<FormatException>(() => CFormat.Sprintf("abc%", 1));
        Assert.Throws<FormatException>(() => CFormat.Sprintf("%n", 1));
    }

    [Fact]
    public void CultureIsIgnored()
    {
        CultureInfo saved = CultureInfo.CurrentCulture;
        try
        {
            var odd = (CultureInfo)CultureInfo.InvariantCulture.Clone();
            odd.NumberFormat.NegativeSign = "~";
            odd.NumberFormat.NumberDecimalSeparator = ",";
            odd.NumberFormat.PositiveSign = "#";
            CultureInfo.CurrentCulture = odd;
            Assert.Equal("-1234.500000 -7 1.5e+10", CFormat.Sprintf("%f %d %g", -1234.5, -7, 1.5e10));
            Assert.Equal(1, CFormat.Sscanf("-1.25", "%lf", out object?[] v));
            Assert.Equal(-1.25, v[0]);
        }
        finally
        {
            CultureInfo.CurrentCulture = saved;
        }
    }

    /*------------------------------- sscanf ----------------------------------*/

    [Fact]
    public void ScanReturnValues()
    {
        Assert.Equal(-1, CFormat.Sscanf("", "%d", out _));
        Assert.Equal(-1, CFormat.Sscanf("   ", "%d", out _));
        Assert.Equal(0, CFormat.Sscanf("abc", "%d", out object?[] v));
        Assert.Null(v[0]);
        Assert.Equal(1, CFormat.Sscanf("5", "%d %d", out v));
        Assert.Equal(5, v[0]);
        Assert.Null(v[1]);
        Assert.Equal(2, CFormat.Sscanf("5 6", "%d %d", out v));
        Assert.Equal(1, CFormat.Sscanf("5 x", "%d %d", out _));
        Assert.Equal(-1, CFormat.Sscanf("", "abc", out _));   // input failure before any conversion
        Assert.Equal(0, CFormat.Sscanf("abc", "abc", out _));
        Assert.Equal(0, CFormat.Sscanf("abd", "abc%d", out _));
    }

    [Fact]
    public void ScanTypesFollowModifiers()
    {
        Assert.Equal(7, CFormat.Sscanf("1 2 3 4 5 6 7", "%hhd %hd %d %ld %lld %zd %I64d", out object?[] v));
        Assert.IsType<sbyte>(v[0]);
        Assert.IsType<short>(v[1]);
        Assert.IsType<int>(v[2]);
        Assert.IsType<int>(v[3]);
        Assert.IsType<long>(v[4]);
        Assert.IsType<long>(v[5]);
        Assert.IsType<long>(v[6]);
        Assert.Equal(7, CFormat.Sscanf("1 2 3 4 5 6 7", "%hhu %hu %u %lu %llu %zu %x", out v));
        Assert.IsType<byte>(v[0]);
        Assert.IsType<ushort>(v[1]);
        Assert.IsType<uint>(v[2]);
        Assert.IsType<uint>(v[3]);
        Assert.IsType<ulong>(v[4]);
        Assert.IsType<ulong>(v[5]);
        Assert.IsType<uint>(v[6]);
        Assert.Equal(3, CFormat.Sscanf("0.1 0.1 0.1", "%f %lf %Lf", out v));
        Assert.IsType<float>(v[0]);
        Assert.IsType<double>(v[1]);
        Assert.IsType<double>(v[2]);
        Assert.Equal(0.1f, v[0] ?? 0f);
        Assert.Equal(0.1, v[1]);
        Assert.Equal(2, CFormat.Sscanf("abc d", "%s %c", out v));
        Assert.Equal("abc", v[0]);
        Assert.Equal("d", v[1]);
    }

    [Fact]
    public void ScanPositionsAndSuppression()
    {
        Assert.Equal(1, CFormat.Sscanf("  12 rest", "%d%n", out object?[] v));
        Assert.Equal(12, v[0]);
        Assert.Equal(4, v[1]);
        Assert.Equal(1, CFormat.Sscanf("1 2", "%*d %d", out v));
        Assert.Single(v);
        Assert.Equal(2, v[0]);
        Assert.Equal(0, CFormat.Sscanf("1 2", "%*d %*d", out v));
        Assert.Empty(v);
        Assert.Equal(1, CFormat.Sscanf("12345", "%2d%n", out v));
        Assert.Equal(12, v[0]);
        Assert.Equal(2, v[1]);
        Assert.Equal(0, CFormat.Sscanf("abc", "%n", out v));
        Assert.Equal(0, v[0]);
        Assert.Equal(1, CFormat.Sscanf("50%", "%d%%", out v));
        Assert.Equal(1, CFormat.Sscanf("0x1F", "%i", out v));
        Assert.Equal(31, v[0]);
        Assert.Equal(1, CFormat.Sscanf("017", "%i", out v));
        Assert.Equal(15, v[0]);
        Assert.Equal(1, CFormat.Sscanf("-12", "%x", out v));
        Assert.Equal(0xFFFFFFEEu, v[0]);   // -0x12
    }

    [Fact]
    public void ScanFloatSpecialAndLimits()
    {
        Assert.Equal(1, CFormat.Sscanf("inf", "%lf", out object?[] v));
        Assert.Equal(double.PositiveInfinity, v[0]);
        Assert.Equal(1, CFormat.Sscanf("-Infinity", "%lf", out v));
        Assert.Equal(double.NegativeInfinity, v[0]);
        Assert.Equal(1, CFormat.Sscanf("nan", "%lf", out v));
        Assert.True(double.IsNaN((double)v[0]!));
        Assert.Equal(1, CFormat.Sscanf("1e999", "%lf", out v));
        Assert.Equal(double.PositiveInfinity, v[0]);
        Assert.Equal(1, CFormat.Sscanf("1e5x", "%f", out v));
        Assert.Equal(1e5f, v[0]);
        Assert.Equal(2, CFormat.Sscanf("1e", "%f%c", out v));
        Assert.Equal("e", v[1]);
    }

    [Fact]
    public void ScanSets()
    {
        Assert.Equal(1, CFormat.Sscanf("abc123", "%[a-z]", out object?[] v));
        Assert.Equal("abc", v[0]);
        Assert.Equal(2, CFormat.Sscanf("abc123", "%[a-z]%[0-9]", out v));
        Assert.Equal("123", v[1]);
        Assert.Equal(1, CFormat.Sscanf("x]y", "%[]x]", out v));
        Assert.Equal("x]", v[0]);
        Assert.Equal(1, CFormat.Sscanf("hello, world", "%[^,]", out v));
        Assert.Equal("hello", v[0]);
        Assert.Equal(0, CFormat.Sscanf(",x", "%[^,]", out _));
        Assert.Equal(1, CFormat.Sscanf("  ab", "%c", out v));
        Assert.Equal(" ", v[0]);
        Assert.Throws<FormatException>(() => CFormat.Sscanf("a", "%[a", out _));
        Assert.Throws<FormatException>(() => CFormat.Sscanf("a", "%", out _));
    }
}
